struct ListNode {
    int val;
    ListNode* next;
    ListNode(int x) : val(x), next(nullptr) {}
};

ListNode* reverseList(ListNode* head) {
    vector<int> vals;
    ListNode* curr = head;
    while (curr) {
        vals.push_back(curr->val);
        curr = curr->next;
    }
    ListNode dummy(0);
    curr = &dummy;
    for (int i = vals.size() - 1; i >= 0; i--) {
        curr->next = new ListNode(vals[i]);
        curr = curr->next;
    }
    return dummy.next;
}

